'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isArray = require( '@stdlib/assert/is-array' );
var zeros = require( '@stdlib/ndarray/zeros' );
var ndarraylike2descriptor = require( '@stdlib/ndarray/base/ndarraylike2descriptor' );
var oneTo = require( '@stdlib/array/one-to' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var setDescriptorOffsets = require( './../lib' );


// MAIN //

bench( format( '%s:len=1', pkg ), function benchmark( b ) {
	var offsets;
	var values;
	var v;
	var i;

	values = [
		ndarraylike2descriptor( zeros( [ 1 ] ) )
	];

	offsets = oneTo( values.length, 'generic' );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		offsets[ 0 ] = i % 4;
		v = setDescriptorOffsets( values, offsets );
		if ( typeof v !== 'object' ) {
			b.fail( 'should return an array' );
		}
	}
	b.toc();
	if ( !isArray( v ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

